/// The entries matching [to] as a session display NAME: a bare name
/// matches `entry.name` exactly; a `name/suffix` form matches the name
/// AND the id suffix (so `goal_builder/main` cannot hit a subagent).
List<MailboxEntry> _nameMatches(List<MailboxEntry> entries, String to) {
  final slash = to.indexOf('/');
  return (slash < 0
          ? entries.where((entry) => entry.name != null && entry.name == to)
          : entries.where(
              (entry) =>
                  entry.id.endsWith('/${to.substring(slash + 1)}') &&
                  entry.name == to.substring(0, slash),
            ))
      .toList();
}

/// Resolves [to] against [entries] as a truncated mailbox id (the short
/// form agent_directory displays, `…` decoration included): a unique
/// prefix returns the one real mailbox id, an ambiguous prefix returns an
/// error listing the candidates, no match returns `(null, null)`.
(String?, String?) _resolveTruncatedId(List<MailboxEntry> entries, String to) {
  final head = to.split('/').first.replaceAll('…', '');
  if (head.isEmpty) return (null, null);
  final matches = [
    for (final entry in entries)
      if (entry.id != to && entry.id.startsWith(head)) entry,
  ];
  if (matches.length == 1) return (matches.single.id, null);
  if (matches.length <= 1) return (null, null);
  final listing = _listMailboxes(matches);
  return (
    null,
    '"$to" is an ambiguous id prefix — pick an exact mailbox:\n$listing',
  );
}

/// Resolves one directory-listed network peer without ever asking the model
/// to copy its opaque encrypted route. Exact ids win; duplicate display names
/// fail closed with the usable ids instead of picking a recipient silently.
/// Exact network-peer ID lookup: `network-dm-N` is a synthetic namespace
/// that cannot collide with local identities, so this match is always
/// safe to take first (PR#2313 review).
(String?, String?) _networkPeerAddressById(SubagentManager manager, String to) {
  for (final peer in manager.networkDmPeers) {
    if (peer.id == to) return (peer.address, null);
  }
  return (null, null);
}

/// Network-peer NAME lookup — must run only AFTER every local identity
/// (selfId, local handles, child names, fabric directory names) declined
/// the string: peer names arrive from the remote side (DM envelope
/// fromName / roster label), so a peer calling itself "main" or a local
/// sibling's display name would otherwise silently hijack local mail
/// onto the encrypted transport (PR#2313 review).
(String?, String?) _resolveNetworkDmPeerAddress(
  SubagentManager manager,
  String to,
) {
  final named = [
    for (final peer in manager.networkDmPeers)
      if (peer.name == to) peer,
  ];
  if (named.isEmpty) return (null, null);
  if (named.length > 1) {
    return (
      null,
      'network DM peer name "$to" is ambiguous — use one of: '
      '${named.map((peer) => peer.id).join(', ')}',
    );
  }
  return (named.single.address, null);
}

/// Last-resort network NAME lookup after every applicable local identity
/// declined [to]. Unknown names retain the manager's own recipient error.
(String, String?) _resolveNetworkPeerNameFallback(
  SubagentManager manager,
  String to,
) {
  final (networkTarget, networkError) = _resolveNetworkDmPeerAddress(
    manager,
    to,
  );
  if (networkError != null) return (to, networkError);
  if (networkTarget != null) return (networkTarget, null);
  return (to, null);
}

/// Resolves [to] against the fabric directory by session display NAME when
/// the raw form does not already hit a deliverable address: a local
/// sibling handle, `main`, or an exact absolute mailbox id. Returns the
/// (possibly rewritten) target plus an error text when the name is
/// ambiguous — an unknown name returns [to] unchanged so the manager's own
/// unknown-recipient error applies.
Future<(String, String?)> _resolveFabricAddress(
  SubagentManager manager,
  String to,
) async {
  // 1. exact network-peer id (synthetic namespace — cannot collide with
  // local identities).
  final (byId, _) = _networkPeerAddressById(manager, to);
  if (byId != null) return (byId, null);
  final fabric = manager.messaging;
  if (fabric == null) {
